def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with cwd if path is relative, otherwise start with /
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        if remaining == '':
            components = []
        else:
            components = remaining.split('/')

        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    # Move to parent directory
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current path is a symlink
            if current in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[current]

                # If target is relative, it's relative to the directory containing the link
                if not target.startswith('/'):
                    link_dir = current.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'
                    target = link_dir + '/' + target if link_dir != '/' else '/' + target

                # Start resolving from the target
                current = '/'
                remaining = target[1:] if target.startswith('/') else target
                break
        else:
            # No more components and no symlink was found
            break

    # Return the canonical path (no trailing slash except for '/')
    if current == '/':
        return '/'
    else:
        return current

